import{_ as i,o as s,c as t,a3 as u,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/vorbereitung/tutorials-broschuerendruck.png",b=JSON.parse('{"title":"Zeugnisse als Broschüre drucken","description":"","frontmatter":{"title":"Zeugnisse als Broschüre drucken","source_pageid":1086,"source_revision":6866},"headers":[],"relativePath":"zeugnisse/vorbereitung/zeugnis-broschuerendruck-mit-dem-foxit-reader-tutorial.md","filePath":"zeugnisse/vorbereitung/zeugnis-broschuerendruck-mit-dem-foxit-reader-tutorial.md"}'),d={name:"zeugnisse/vorbereitung/zeugnis-broschuerendruck-mit-dem-foxit-reader-tutorial.md"};function o(l,r,c,h,g,k){return s(),t("div",null,[...r[0]||(r[0]=[u('<h1 id="zeugnisse-als-broschure-drucken" tabindex="-1">Zeugnisse als Broschüre drucken <a class="header-anchor" href="#zeugnisse-als-broschure-drucken" aria-label="Permalink to &quot;Zeugnisse als Broschüre drucken&quot;">​</a></h1><p>Drucken Sie mehrseitige Zeugnisse mit passender Seitenfolge und Wendung als Broschüre. Die Anleitung unterscheidet Druckertreiber und PDF-Druck mit Foxit Reader.</p><p><a href="/bilder/vorbereitung/tutorials-broschuerendruck.png"><img src="'+a+'" alt="Zeugnisse als Broschüre drucken." loading="lazy"></a></p><p><em>Zeugnisse als Broschüre drucken.</em></p><p>Je nach verwendetem Druckertreiber lassen sich Zeugnisse in SchILD-NRW 3 über Windows-Bordmittel als Broschüre drucken, also doppelseitig mit korrekter Wendung. Besonders größere und professionelle Drucksysteme stellen diese Option direkt im Druckertreiber bereit.</p><p>Dies ist insbesondere für vierseitige Zeugnisse relevant, die auf ein A3-Blatt gedruckt werden, zum Beispiel Abschluss- oder Abgangszeugnisse.</p><p>Die konkreten Einstellungen hängen vom verwendeten Druckerhersteller und dem jeweiligen Druckertreiber ab.</p><h2 id="broschurendruck-uber-einen-windows-druckertreiber" tabindex="-1">Broschürendruck über einen Windows-Druckertreiber <a class="header-anchor" href="#broschurendruck-uber-einen-windows-druckertreiber" aria-label="Permalink to &quot;Broschürendruck über einen Windows-Druckertreiber&quot;">​</a></h2><p>Wählen Sie für Abschluss- und Abgangszeugnisse im Druckdialog die Option <em>Broschüre</em> (oder eine entsprechend benannte Einstellung) und stellen Sie das Papierformat auf A3 ein.</p><p>Es wird dann eine Broschüre erzeugt, die nach dem Falten ein A4-Zeugnis ergibt. Dabei bilden die Seiten 1 und 4 den äußeren Teil und die Seiten 2 und 3 den inneren Teil des Zeugnisses.</p><h2 id="broschurendruck-mit-dem-foxit-reader" tabindex="-1">Broschürendruck mit dem Foxit-Reader <a class="header-anchor" href="#broschurendruck-mit-dem-foxit-reader" aria-label="Permalink to &quot;Broschürendruck mit dem Foxit-Reader&quot;">​</a></h2><p>Für den Broschürendruck mit dem Foxit Reader steht eine separate Anleitung zur Verfügung: <a href="https://www.svws.nrw.de/system/files/media/document/file/broschuerendruck.pdf" target="_blank" rel="noreferrer">Broschürendruck – Anleitung</a></p><p>Im Foxit Reader heißt der Broschürendruck <em>Booklet</em>. Vergleichbare Funktionen werden häufig auch von anderen PDF-Programmen angeboten.</p><p>Die Anleitung ist in zwei Schritte gegliedert:</p><ol><li>Erzeugen der PDF-Zeugnisse aus SchILD-NRW 3</li><li>Drucken der PDF-Zeugnisse mit dem Foxit Reader als Broschüre</li></ol><p>Der Foxit Reader wird verwendet, da eine kostenlose Version verfügbar ist, die für den Broschürendruck ausreicht. Der Download-Link ist in der Anleitung enthalten.</p><p>Die beschriebenen Schritte lassen sich in der Regel auch auf PDF-Reader anderer Hersteller übertragen.</p>',17),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis – Siehe auch")]),e("ul",null,[e("li",null,[e("a",{href:"/reporting/zeugnisformulare/zeugnisse-themenuebersicht.html"},"Den Zeugnisdruck vorbereiten")]),e("li",null,[e("a",{href:"/reporting/zeugnisformulare/zeugnisformulare-herunterladen-und-aktualisieren.html"},"Zeugnisformulare herunterladen und bereitstellen")])])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Zeugnis-Brosch%C3%BCrendruck_mit_dem_Foxit_Reader_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6866.")],-1)])])}const p=i(d,[["render",o]]);export{b as __pageData,p as default};
